// Stored dag definitions for JavaScript eval cells: load a named definition from the dag library
// directories and start it, without pasting the full definition JSON into the cell. Like sdk.js
// this file must stay import-free: the eval worker has no node_modules on its resolver path, and
// the globals it needs (`read`, `env`, `tool`) are injected by the kernel at call time.
//
// Library dirs, first hit wins: $OMO_DAG_LIBRARY (colon-separated), $PWD/.omo/dags, $HOME/.omo/dags.
// A definition is the plain dag definition JSON with two extras: string values may carry
// {{key}} / {{date}} / {{datetime}} placeholders, and `key` is treated as a base key that load()
// rotates with a suffix so the same stored graph can run repeatedly (suffix "" keeps it idempotent).

function kernel(name) {
  const value = globalThis[name]
  if (value === undefined || value === null) {
    throw new Error(`dag library: the eval kernel global \`${name}\` is unavailable here.`)
  }
  return value
}

function libraryDirs() {
  const env = kernel("env")
  const dirs = []
  const configured = env("OMO_DAG_LIBRARY")
  if (typeof configured === "string" && configured !== "") {
    const separator = globalThis.process?.platform === "win32" ? ";" : ":"
    dirs.push(...configured.split(separator).filter((dir) => dir !== ""))
  }
  const pwd = env("PWD")
  if (typeof pwd === "string" && pwd !== "") dirs.push(`${pwd}/.omo/dags`)
  const home = env("HOME")
  if (typeof home === "string" && home !== "") dirs.push(`${home}/.omo/dags`)
  return dirs
}

async function readDefinitionText(name, dirs) {
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(name)) {
    throw new Error(`dag library: invalid definition name "${name}" (letters, digits, dot, dash, underscore).`)
  }
  const read = kernel("read")
  for (const dir of dirs) {
    try {
      return await read(`${dir}/${name}.json`)
    } catch {
    }
  }
  throw new Error(`dag library: definition "${name}" not found. Searched: ${dirs.join(", ")}`)
}

function utcVars(finalKey, now) {
  const stamp = now.toISOString()
  const date = stamp.slice(0, 10).replaceAll("-", "")
  const datetime = `${date}-${stamp.slice(11, 19).replaceAll(":", "")}`
  return { key: finalKey, date, datetime }
}

function fillPlaceholders(value, vars) {
  if (typeof value === "string") {
    return value.replaceAll("{{key}}", vars.key).replaceAll("{{date}}", vars.date).replaceAll("{{datetime}}", vars.datetime)
  }
  if (Array.isArray(value)) {
    return value.map((entry) => fillPlaceholders(entry, vars))
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([field, entry]) => [field, fillPlaceholders(entry, vars)]))
  }
  return value
}

export async function load(name, options) {
  const text = await readDefinitionText(name, libraryDirs())
  const definition = JSON.parse(text)
  if (typeof definition.key !== "string" || definition.key === "") {
    throw new Error(`dag library: definition "${name}" needs a non-empty string key (the base idempotency key).`)
  }
  if (!Array.isArray(definition.nodes) || definition.nodes.length === 0) {
    throw new Error(`dag library: definition "${name}" needs a non-empty nodes array.`)
  }
  const suffix = options?.suffix
  const now = new Date()
  const finalKey = suffix === "" ? definition.key : `${definition.key}-${suffix ?? utcVars("", now).datetime}`
  return { ...fillPlaceholders(definition, utcVars(finalKey, now)), key: finalKey }
}

// Mirrors sdk.js: a refused start resolves with { details: { kind: "error", error: { code, message } } }
// and no run_id, so surface the tool's own words instead of the missing-run_id symptom.
function throwIfToolError(action, response) {
  if (response?.details?.kind !== "error") return response
  const error = response.details.error
  const code = typeof error?.code === "string" && error.code !== "" ? error.code : undefined
  const message = typeof error?.message === "string" && error.message !== "" ? error.message : undefined
  const detail =
    code === undefined && message === undefined
      ? firstContentText(response) ?? "the dag tool reported an error with no details."
      : [code, message].filter((part) => part !== undefined).join(": ")
  throw new Error(`dag library: ${action} failed: ${detail}`)
}

function firstContentText(response) {
  const content = response?.content
  if (!Array.isArray(content)) return undefined
  for (const entry of content) {
    if (typeof entry?.text === "string" && entry.text !== "") return entry.text
  }
  return undefined
}

export async function start(name, options) {
  const definition = await load(name, options)
  const response = throwIfToolError("start", await kernel("tool").workflow({ action: "start", definition }))
  const runId = response?.details?.run_id ?? response?.run_id
  if (typeof runId !== "string" || runId === "") {
    throw new Error("dag library: the dag start response did not include a run_id.")
  }
  const workflow = kernel("tool").workflow
  return {
    ...response,
    run_id: runId,
    // done() blocks for the final result, opting out of the tool's detached default.
    done: () => workflow({ action: "wait", run_id: runId, detach: false }),
    cancel: (reason) =>
      reason === undefined
        ? workflow({ action: "cancel", run_id: runId })
        : workflow({ action: "cancel", run_id: runId, reason }),
  }
}

// Dependency-free convenience wrapper around the `dag` tool, loaded by JavaScript eval cells from
// OMO_DAG_SDK_ROOT. It must stay import-free: the eval worker has no node_modules on its resolver
// path, so anything this file imports would break the cell at load time.
//
// Every call funnels through globalThis.tool.workflow({ action, ... }), the proxy the JS kernel installs
// (senpi packages/senpi-codemode/src/kernels/js/worker-runtime.js). Python cells cannot import ESM
// and call tool.workflow({...}) directly instead; there is no Python counterpart to this file.

// The dag tool reports a refusal in-band: it resolves with { details: { kind: "error", error: { code,
// message, ... } } } and no run_id (see packages/omo-senpi/src/components/task/dag-tool-contract.ts).
// Every action funnels through here so a refusal reaches the cell as the tool's own code and message
// rather than as a downstream symptom such as a missing run_id.
function throwIfToolError(action, response) {
  if (response?.details?.kind !== "error") return response
  const error = response.details.error
  const code = typeof error?.code === "string" && error.code !== "" ? error.code : undefined
  const message = typeof error?.message === "string" && error.message !== "" ? error.message : undefined
  const detail =
    code === undefined && message === undefined
      ? firstContentText(response) ?? "the dag tool reported an error with no details."
      : [code, message].filter((part) => part !== undefined).join(": ")
  throw new Error(`dag ${action} failed: ${detail}`)
}

function firstContentText(response) {
  const content = response?.content
  if (!Array.isArray(content)) return undefined
  for (const entry of content) {
    if (typeof entry?.text === "string" && entry.text !== "") return entry.text
  }
  return undefined
}

async function callDag(args) {
  const proxy = globalThis.tool
  if (proxy === undefined || proxy === null || typeof proxy.workflow !== "function") {
    throw new Error("The dag sdk requires the eval kernel's global `tool` proxy; it is unavailable here.")
  }
  return throwIfToolError(args.action, await proxy.workflow(args))
}

class DagDefinitionBuilder {
  constructor(key, name) {
    this.key = key
    this.name = name
    this.nodes = []
    this.ids = new Set()
  }

  // Rejects duplicates locally so a mistyped graph fails in the cell, before any host round-trip.
  node(input) {
    if (input === undefined || input === null || typeof input.id !== "string" || input.id === "") {
      throw new Error("A dag node needs a non-empty string id.")
    }
    if (this.ids.has(input.id)) {
      throw new Error(`Duplicate dag node id "${input.id}": every node id must be unique within a definition.`)
    }
    this.ids.add(input.id)
    this.nodes.push(input)
    return this
  }

  definition() {
    return this.name === undefined
      ? { key: this.key, nodes: this.nodes }
      : { key: this.key, name: this.name, nodes: this.nodes }
  }

  start() {
    return start(this.definition())
  }
}

export function define(input) {
  if (input === undefined || input === null || typeof input.key !== "string" || input.key === "") {
    throw new Error("define() needs a non-empty string key: it is the run's idempotency key.")
  }
  return new DagDefinitionBuilder(input.key, input.name ?? input.key)
}

function runHandle(response, runId) {
  return {
    ...response,
    run_id: runId,
    done: () => wait(runId),
    cancel: (reason) => cancel(runId, reason),
  }
}

export async function start(definition) {
  const response = await callDag({ action: "start", definition })
  const runId = response?.details?.run_id ?? response?.run_id
  if (typeof runId !== "string" || runId === "") {
    throw new Error("The dag start response did not include a run_id.")
  }
  return runHandle(response, runId)
}

export async function attach(runId) {
  const response = await callDag({ action: "attach", run_id: runId })
  return runHandle(response, runId)
}

export function snapshot(runId) {
  return callDag({ action: "snapshot", run_id: runId })
}

export function wait(runId) {
  // A cell cannot receive the session's wake injections, so the SDK keeps the blocking contract.
  return callDag({ action: "wait", run_id: runId, detach: false })
}

export function cancel(runId, reason) {
  return reason === undefined
    ? callDag({ action: "cancel", run_id: runId })
    : callDag({ action: "cancel", run_id: runId, reason })
}

/**
 * Retry one or more failed/cancelled/skipped DAG nodes in place.
 *
 * @param {string} runId - The run id returned by start/attach.
 * @param {string | string[] | undefined} nodeIds - A single node id, an array of node ids, or omitted to retry all eligible nodes.
 * @param {{ prompt?: string } | undefined} opts - Optional per-node overrides. `prompt` is only meaningful for a single-node retry.
 * @returns {Promise<unknown>} The dag tool response.
 */
export function retry(runId, nodeIds, opts) {
  if (typeof runId !== "string" || runId === "") {
    throw new Error("retry() needs a non-empty string run_id.")
  }
  const payload = { action: "retry", run_id: runId }
  if (nodeIds !== undefined) {
    if (Array.isArray(nodeIds)) {
      payload.node_ids = nodeIds
    } else if (typeof nodeIds === "string") {
      payload.node_id = nodeIds
    } else {
      throw new Error("retry() nodeIds must be a string or string[] when provided.")
    }
  }
  if (opts !== undefined && opts !== null) {
    if (typeof opts.prompt === "string") {
      payload.prompt = opts.prompt
    } else if (opts.prompt !== undefined) {
      throw new Error("retry() opts.prompt must be a string when provided.")
    }
  }
  return callDag(payload)
}

/**
 * Send a steering message to a node's child task.
 *
 * @param {string} runId - The run id.
 * @param {string} nodeId - The target node id.
 * @param {string} message - The message to deliver to the child.
 * @returns {Promise<unknown>} The dag tool response.
 */
export function send(runId, nodeId, message) {
  if (typeof runId !== "string" || runId === "") {
    throw new Error("send() needs a non-empty string run_id.")
  }
  if (typeof nodeId !== "string" || nodeId === "") {
    throw new Error("send() needs a non-empty string node_id.")
  }
  if (typeof message !== "string" || message === "") {
    throw new Error("send() needs a non-empty string message.")
  }
  return callDag({ action: "send", run_id: runId, node_id: nodeId, message })
}

/**
 * Amend the definition of an existing run. Unchanged completed nodes are reused;
 * changed nodes and their transitive dependents are re-run.
 *
 * @param {string} runIdOrKeySelector - The run id of the run to amend. (The SDK accepts a run id; a key selector may be supported later.)
 * @param {Record<string, unknown>} definition - The new DAG definition, using the same schema as start().
 * @returns {Promise<unknown>} The dag tool response.
 */
export function amend(runIdOrKeySelector, definition) {
  if (typeof runIdOrKeySelector !== "string" || runIdOrKeySelector === "") {
    throw new Error("amend() needs a non-empty string run_id selector.")
  }
  if (definition === undefined || definition === null || typeof definition !== "object") {
    throw new Error("amend() needs a definition object.")
  }
  return callDag({ action: "amend", run_id: runIdOrKeySelector, definition })
}

import { createHash } from "node:crypto"
import { spawn } from "node:child_process"
import { readFile, writeFile } from "node:fs/promises"
import { relative, resolve } from "node:path"
import { createInterface } from "node:readline"
import { fileURLToPath } from "node:url"
import { minify } from "terser"

const BUILD_MARKER_PREFIX = "// omo:"
const BUILD_ARTIFACT_PATH = fileURLToPath(import.meta.url)
const MINIFIER_IDLE_MS = 5_000

let minifierRequestId = 0
let nodeMinifier

export async function normalizeBuiltinImports(output, builtinModuleNames) {
  const bundled = await readFile(output, "utf8")
  const normalized = bundled.replace(
    /(from\s*["']|import\s*\(\s*["']|import\s*["'])([^"']+)(["'])/g,
    (match, prefix, specifier, suffix) => {
      if (specifier.startsWith("node:")) return match
      if (!builtinModuleNames.includes(specifier)) return match
      return `${prefix}node:${specifier}${suffix}`
    },
  ).replace(/^[\t ]+$/gm, "")
  if (normalized !== bundled) await writeFile(output, normalized)
}

export async function minifyBundle(output) {
  if (process.versions.bun !== undefined) {
    await minifyBundleWithNode(output)
    return
  }
  await minifyBundleInProcess(output)
}

async function minifyBundleInProcess(output) {
  const result = await minify(await readFile(output, "utf8"), {
    compress: true,
    mangle: true,
    module: true,
  })
  if (typeof result.code !== "string") {
    throw new Error(`Terser did not produce code for ${output}`)
  }
  await writeFile(output, result.code)
}

function minifyBundleWithNode(output) {
  const minifier = getNodeMinifier()
  clearTimeout(minifier.idleTimer)
  const id = ++minifierRequestId
  return new Promise((resolvePromise, reject) => {
    minifier.pending.set(id, { resolve: resolvePromise, reject })
    minifier.child.stdin.write(`${JSON.stringify({ id, output })}\n`, (error) => {
      if (error === null || error === undefined) return
      minifier.pending.delete(id)
      reject(error)
    })
  })
}

function getNodeMinifier() {
  if (
    nodeMinifier !== undefined
    && nodeMinifier.child.stdin.writable
    && !nodeMinifier.child.stdin.writableEnded
    && !nodeMinifier.child.stdin.destroyed
  ) return nodeMinifier
  nodeMinifier = undefined
  const child = spawn("node", [BUILD_ARTIFACT_PATH, "--minify-server"], {
    stdio: ["pipe", "pipe", "inherit"],
    windowsHide: true,
  })
  const pending = new Map()
  const lines = createInterface({ input: child.stdout })
  const minifier = { child, pending, idleTimer: undefined }
  nodeMinifier = minifier
  lines.on("line", (line) => {
    const response = JSON.parse(line)
    const request = pending.get(response.id)
    if (request === undefined) return
    pending.delete(response.id)
    if (response.error === undefined) request.resolve()
    else request.reject(new Error(response.error))
    minifier.idleTimer = setTimeout(() => closeNodeMinifier(minifier), MINIFIER_IDLE_MS)
  })
  child.on("exit", (code, signal) => {
    clearTimeout(minifier.idleTimer)
    if (nodeMinifier === minifier) nodeMinifier = undefined
    const reason = new Error(`Node minifier exited before completing requests: code=${String(code)} signal=${String(signal)}`)
    for (const request of pending.values()) request.reject(reason)
    pending.clear()
  })
  return minifier
}

export function closeNodeMinifier(minifier = nodeMinifier) {
  if (minifier === undefined) return
  clearTimeout(minifier.idleTimer)
  if (nodeMinifier === minifier) nodeMinifier = undefined
  minifier.child.stdin.end()
}

export async function attachBuildMarker(options) {
  const body = await readFile(options.output, "utf8")
  const metadata = JSON.parse(await readFile(options.metafile, "utf8"))
  const sourceDigest = await digestBuildSources(metadata, options)
  // Node's ESM loader only strips a shebang when it is the first bytes of the file, so an
  // executable bundle must keep it there and carry the marker on the line below. The digest still
  // covers the whole body, shebang included, so freshness is unaffected by where the marker sits.
  const marker = `${BUILD_MARKER_PREFIX}${sourceDigest}:${digest(body)}`
  const shebang = body.startsWith("#!") ? body.slice(0, body.indexOf("\n") + 1) : ""
  await writeFile(options.output, `${shebang}${marker}\n${body.slice(shebang.length)}`)
  return Object.keys(metadata.inputs ?? {})
}

async function digestBuildSources(metadata, options) {
  const inputs = metadata !== null && typeof metadata === "object" && metadata.inputs !== null
    && typeof metadata.inputs === "object" ? Object.keys(metadata.inputs).sort() : []
  const hash = createHash("sha256")
    .update(options.buildSettings)
    .update(JSON.stringify(options.buildDefines))
    .update(toPortableBuildPath(relative(options.repoRoot, options.entry)))
  for (const input of inputs) {
    const inputPath = resolve(options.repoRoot, input)
    hash.update(toPortableBuildPath(relative(options.repoRoot, inputPath))).update(await readFile(inputPath))
  }
  hash.update(await readFile(options.buildScriptPath))
  hash.update(await readFile(fileURLToPath(import.meta.url)))
  return hash.digest("base64url")
}

export function artifactsMatch(currentText, expectedText) {
  const current = parseBuildArtifact(currentText)
  const expected = parseBuildArtifact(expectedText)
  return current !== undefined && expected !== undefined
    && current.sourceDigest === expected.sourceDigest
    && current.bodyDigest === digest(current.body)
    && expected.bodyDigest === digest(expected.body)
    && current.bodyDigest === expected.bodyDigest
    && current.body === expected.body
}

function parseBuildArtifact(text) {
  // Executable bundles keep the shebang at byte 0 (Node only strips it there) and carry the marker
  // on the line below, so the marker is not always the first line. The digested body is everything
  // except the marker line, shebang included, matching how attachBuildMarker composes the file.
  const offset = text.startsWith("#!") ? text.indexOf("\n") + 1 : 0
  if (offset < 0) return undefined
  const marked = text.slice(offset)
  const newline = marked.indexOf("\n")
  if (newline < 0) return undefined
  const match = /^\/\/ omo:([A-Za-z0-9_-]{43}):([A-Za-z0-9_-]{43})$/.exec(marked.slice(0, newline))
  if (match === null) return undefined
  return {
    sourceDigest: match[1],
    bodyDigest: match[2],
    body: text.slice(0, offset) + marked.slice(newline + 1),
  }
}

function digest(value) {
  return createHash("sha256").update(value).digest("base64url")
}

export function toPortableBuildPath(path) {
  return path.replaceAll("\\", "/")
}

if (resolve(process.argv[1] ?? "") === resolve(BUILD_ARTIFACT_PATH)) {
  if (process.argv[2] === "--minify") {
    const output = process.argv[3]
    if (output === undefined) throw new Error("missing bundle path for --minify")
    await minifyBundleInProcess(output)
  } else if (process.argv[2] === "--minify-server") {
    const lines = createInterface({ input: process.stdin, crlfDelay: Infinity })
    for await (const line of lines) {
      const request = JSON.parse(line)
      try {
        await minifyBundleInProcess(request.output)
        process.stdout.write(`${JSON.stringify({ id: request.id })}\n`)
      } catch (error) {
        process.stdout.write(`${JSON.stringify({ id: request.id, error: error instanceof Error ? error.message : String(error) })}\n`)
      }
    }
  }
}

import { createHash } from "node:crypto"
