export function createNativeSkillSources(repoRoot) {
  const nativeSkillsRoot = join(repoRoot, "omo-senpi", "skills")

  /** @type {SkillSource[]} */
  const sources = [
    {
      name: "dag-library",
      source: join(nativeSkillsRoot, "dag-library"),
    },
    {
      name: "give-me-tips",
      source: join(nativeSkillsRoot, "give-me-tips"),
