const defaultSourceDist = process.env.OMO_LSP_DAEMON_DIST ?? join(repoRoot, "packages", "lsp-daemon", "dist")
const defaultTargetDist = process.env.OMO_LSP_DAEMON_TARGET ?? join(pluginRoot, "runtime", "lsp-daemon", "dist")

